/// The number of lines in which two programs differ.
fn differing_lines(a: &str, b: &str) -> usize {
    let (a, b): (Vec<&str>, Vec<&str>) = (a.lines().collect(), b.lines().collect());
    if a.len() != b.len() {
        return usize::MAX;
    }
    a.iter().zip(&b).filter(|(x, y)| x != y).count()
}

fn check(
    name: &str,
    program: &str,
    args: &[&str],
    raw: bool,
    (outcome, want): Expect,
) -> Vec<String> {
    let run = if raw {
        common::run_raw(name, program, args)
    } else {
        common::run(name, program, args)
    };
    let mut problems = Vec::new();
    if run.outcome() != outcome {
        problems.push(format!(
            "{name}: outcome {} instead of {outcome}",
            run.outcome()
        ));
    }
    let errors: Vec<(String, usize)> = run
        .errors()
        .iter()
        .map(|d| {
            (
                d.message.clone(),
                d.primary_lines.first().copied().unwrap_or(0),
            )
        })
        .collect();
    let matches = errors.len() == want.len()
        && errors
            .iter()
            .zip(want)
            .all(|((message, line), (prefix, want_line))| {
                message.starts_with(prefix) && line == want_line
            });
    if !matches {
        problems.push(format!("{name}: errors {errors:?} instead of {want:?}"));
    }
    if !run.raw.is_empty() {
        problems.push(format!("{name}: non-JSON stderr {:?}", run.raw));
    }
    if outcome == "checked" && run.exit != 0 {
        problems.push(format!("{name}: exit {} for a checked run", run.exit));
    }
    problems
}

#[test]
fn false_passes_and_their_twins() {
    let cases: Vec<(&Case, bool)> = CASES
        .iter()
        .map(|case| (case, false))
        .chain(RAW_CASES.iter().map(|case| (case, true)))
        .collect();
    for (case, _) in &cases {
        assert_eq!(
            differing_lines(case.program, case.twin),
            1,
            "{}: the twin is not a one-line change",
            case.name
        );
    }
    // Each run starts a compiler; four at a time.
    let next = AtomicUsize::new(0);
    let problems = Mutex::new(Vec::new());
    std::thread::scope(|scope| {
        for _ in 0..4 {
            scope.spawn(|| loop {
                let i = next.fetch_add(1, Ordering::Relaxed);
                let Some(&(case, raw)) = cases.get(i) else {
                    break;
                };
                let mut found = check(case.name, case.program, case.args, raw, case.expect);
                let twin = format!("{}__twin", case.name);
                found.extend(check(&twin, case.twin, case.args, raw, case.twin_expect));
                problems.lock().expect("lock").extend(found);
            });
        }
    });
    let problems = problems.into_inner().expect("lock");
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}
